# Android supports numbered placeholders in any word order; the existing generator also checks
# occurrence order, so these four translations phrase the count in that order explicitly.
ROWS['tr-TR'] = ROWS['tr-TR'].replace('%2$d dosyadan %1$d tanesi', '%1$d / %2$d dosya')
ROWS['hi'] = ROWS['hi'].replace('%2$d में से %1$d फ़ाइलें', '%1$d / %2$d फ़ाइलें')
ROWS['ja-JP'] = ROWS['ja-JP'].replace('%2$d個中%1$d個のファイル', '%1$d / %2$d個のファイル')
ROWS['ko-KR'] = ROWS['ko-KR'].replace('%2$d개 중 %1$d개 파일', '%1$d / %2$d개 파일')
path = Path(__file__).with_name('catalog.json')
catalog = json.loads(path.read_text(encoding='utf-8'))
assert set(ROWS) == set(catalog['locales'])
for key in KEYS:
    if key not in catalog['keys']:
        catalog['keys'].append(key)
        for values in catalog['locales'].values(): values.append('')
for locale, row in ROWS.items():
    values = row.split('|'); assert len(values) == len(KEYS), locale
    for key, value in zip(KEYS, values): catalog['locales'][locale][catalog['keys'].index(key)] = value
path.write_text(json.dumps(catalog, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
